using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {public static class FleetKitExporter {
 public static void Export(GameObject root){var layout=root.GetComponentInChildren<ParkingTrainingLayout>();string folder=ContextBuilder.W+"/ReusableVehicles";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var lines=new List<string>{"Reusable vehicle kit. Root at ground level; nose +Z. Uses final map paint, glass, wheel and tire materials; plates are attached. Import these prefabs directly for future layouts instead of slicing meshes or redoing materials.","Porter attribution is retained in ../PorterData/CREDITS.txt; other model credits are in Assets/ParkingLotEnvironment/VEHICLE-SOURCES.md and CREDITS.md."};foreach(var o in layout.obstacles){var source=layout.transform.Find(o.id);var b=ContextBuilder.BoundsOf(source.gameObject);var canonical=new GameObject("Vehicle_"+o.id);var anchor=new GameObject("CanonicalForward").transform;anchor.SetParent(canonical.transform,false);var clone=UnityEngine.Object.Instantiate(source.gameObject,anchor);clone.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);anchor.localRotation=Quaternion.Euler(0,o.id.StartsWith("Parked_T_")?-90:o.id.Contains("BoxTruck")?0:180,0);foreach(var r in clone.GetComponentsInChildren<MeshRenderer>()){r.lightmapIndex=-1;r.receiveGI=ReceiveGI.LightProbes;GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.ReflectionProbeStatic);}string key=o.id=="Parked_T_0"?"Hyundai_i30_Black":o.id=="Parked_T_1"?"Hyundai_Tucson_White":o.id=="Parked_T_3"?"Hyundai_Azera_Navy":o.id=="Parked_T_6"?"Hyundai_i30_Burgundy":o.id=="Parked_T_8"?"Hyundai_Tucson_Graphite":o.id=="Parked_T_9"?"Hyundai_Azera_Silver":o.id=="Parked_P_Front"?"Hyundai_i30_Blue":o.id=="Parked_P_Rear"?"Hyundai_Tucson_Black":o.id.Contains("PortedModel")?"Hyundai_Porter_II_Blue":"Generic_DeliveryTruck";string path=folder+"/"+key+".prefab";if(File.Exists(path))throw new Exception("Reusable vehicle already exists");PrefabUtility.SaveAsPrefabAsset(canonical,path);UnityEngine.Object.DestroyImmediate(canonical);lines.Add(path+" | "+o.category+" | "+o.model);}File.WriteAllLines(folder+"/READ-ME.txt",lines);AssetDatabase.Refresh();}
}}
